//! This is a constant generator for `constants.rs`.
//! This is ugly, but there are many things practically requiring allocation or
//! otherwise can't be done in a `const fn`, and some constant bootstraps take a
//! significant amount of time to calculate and would add to compilation time

use std::fmt::Write;

use common::sqrt::simple_isqrt_lut;
use fracints::{Fracint, fi16};

// The master trigonometry values below are magnitudes in Q127 fixed point
// (i.e. `round(value * 2^127)`), generated by `gen_trig_master.py` in the
// `testcrate` directory, which computes them with 320-bit integer fixed point
// arithmetic (pi is derived from scratch with Machin's formula), so they are
// correctly rounded at this width. All the narrower constants are derived from
// these by round-to-nearest shifts.

/// `a_k = (pi/4)^(2k) / (2k)!`, the coefficient magnitudes of the alternating
/// series `cos((pi/4)*t) = a_0 - a_1*t^2 + a_2*t^4 - ...`. `a_0 = 1.0` is
/// saturated to `MAX`.
const MASTER_COS: [u128; 16] = [
    170141183460469231731687303715884105727,
    52475817908999972505782598074850543282,
    2697476892632447462304736525886010442,
    55464645440337605747557706865614254,
    610953246364750960627892584840009,
    4187407534153734215659464606864,
    19568208252006834270457412117,
    66322278257362553798162472,
    170462148275817327813015,
    343626219126256846934,
    557805073127993572,
    744766694357957,
    832263659921,
    789818565,
    644444,
    457,
];

/// `b_k = (pi/4)^(2k+1) / (2k+1)!`, the coefficient magnitudes of the
/// alternating series `sin((pi/4)*t) = t*(b_0 - b_1*t^2 + b_2*t^4 - ...)`
const MASTER_SIN: [u128; 16] = [
    133628573008120843482460046645233847913,
    13738137002835834898907806932589814914,
    423718679456116020458444704270379203,
    6223118666047401603949173861017025,
    53315728624064907494611424623963,
    298980198792816423517315782738,
    1182218063238843076263849110,
    3472626369044471224087581,
    7875332834388849369035,
    14204389547209013294,
    20861860950881214,
    25432104082971,
    26146333999,
    22974891,
    17453,
    12,
];

/// sqrt(1/2)
const MASTER_SQRT_HALF: u128 = 120307984584002255772516886238812528464;
/// 1/pi
const MASTER_INV_PI: u128 = 54157620742477409023451113735280473968;

// Chebyshev economized coefficient magnitudes for the same series shapes as
// above, used by the `_fast` variants. The degree 2 tables have a maximum
// polynomial error around 1.0e-5 and the degree 3 tables around 2.8e-8.
const MASTER_COS_FAST_DEG2: [u128; 3] = [
    170139483308948547553517050688671055872,
    52445149236244833775909975246157905920,
    2615341278971286374269242737552261120,
];
const MASTER_SIN_FAST_DEG2: [u128; 3] = [
    133628381430439221501838671538812878848,
    13734682835885494189446741302557278208,
    414476745673580168941496548370415616,
];
const MASTER_COS_FAST_DEG3: [u128; 4] = [
    170141178760480513577620888922540212224,
    52475667363820259988710926412964429824,
    2696722952505746436808273203942129664,
    54254449022973221303153030013648896,
];
const MASTER_SIN_FAST_DEG3: [u128; 4] = [
    133628572596815468004946303374233436160,
    13738123830658046943362944646435045376,
    423652731733720600094784482583773184,
    6117324040093616925786940786081792,
];

/// Round-to-nearest of a Q127 magnitude to Q(w-1), saturating to the fracint
/// `MAX` of the width
fn round_master(x: u128, w: u32) -> u128 {
    let max = (1u128 << (w - 1)) - 1;
    if w == 128 {
        x.min(max)
    } else {
        let shift = 128 - w;
        ((x + (1u128 << (shift - 1))) >> shift).min(max)
    }
}

/// The number of leading coefficients that a width `w` evaluation needs: a
/// coefficient is kept if it is at least a quarter of the width's ULP, i.e.
/// `2^-(w+1)`, so that the dropped tail contributes well under an ULP
fn nterms(master: &[u128], w: u32) -> usize {
    let threshold = if w >= 127 { 1 } else { 1u128 << (126 - w) };
    master.iter().take_while(|&&a| a >= threshold).count()
}

fn table(master: &[u128], terms: usize, w: u32) -> String {
    let mut s = "&[".to_owned();
    for (i, &a) in master.iter().take(terms).enumerate() {
        let r = round_master(a, w);
        // a trailing coefficient that rounds to zero at this width
        // contributes nothing
        if r == 0 {
            break;
        }
        if i != 0 {
            s += ", ";
        }
        write!(s, "fi{w}({r})").unwrap();
    }
    s += "]";
    s
}

pub fn main() {
    let mut s = r#"// The generating function is in the testcrate of the repo containing this
// crate.
use fracints_internals::TrigConsts;

use crate::impl_signed::*;

"#
    .to_owned();

    for w in [8u32, 16, 32, 64, 128] {
        // the accurate tables are evaluated at double width when one exists
        let wd = if w == 128 { 128 } else { 2 * w };
        let (cos_fast, sin_fast): (&[u128], &[u128]) = if w <= 16 {
            (&MASTER_COS_FAST_DEG2, &MASTER_SIN_FAST_DEG2)
        } else {
            (&MASTER_COS_FAST_DEG3, &MASTER_SIN_FAST_DEG3)
        };
        writeln!(
            s,
            r#"pub const FI{w}_TRIG: TrigConsts<fi{w}, fi{wd}> = TrigConsts {{
    sqrt_half: fi{w}({sqrt_half}),
    inv_pi: fi{w}({inv_pi}),
    cos_coeffs: {cos},
    sin_coeffs: {sin},
    cos_coeffs_fast: {cos_fast},
    sin_coeffs_fast: {sin_fast},
}};
"#,
            sqrt_half = round_master(MASTER_SQRT_HALF, w),
            inv_pi = round_master(MASTER_INV_PI, w),
            cos = table(&MASTER_COS, nterms(&MASTER_COS, w), wd),
            sin = table(&MASTER_SIN, nterms(&MASTER_SIN, w), wd),
            cos_fast = table(cos_fast, nterms(cos_fast, w), w),
            sin_fast = table(sin_fast, nterms(sin_fast, w), w),
        )
        .unwrap()
    }

    // isqrt table
    let n = 24;
    // find by setting to 1.0 and using the x value
    let cutoff = fi16!(0.99936);
    let (lut, bits) = simple_isqrt_lut(n, cutoff);
    writeln!(s, r#"pub const SIMPLE_ISQRT_LUT: [fi16; {n}] = ["#).unwrap();
    for entry in lut {
        writeln!(s, r#"    fi16({}),"#, entry.as_int()).unwrap();
    }
    writeln!(s, r#"];"#).unwrap();

    writeln!(
        s,
        r#"pub const SIMPLE_ISQRT_CUTOFF: fi16 = fi16({});"#,
        cutoff.as_int(),
    )
    .unwrap();
    writeln!(s, r#"pub const SIMPLE_ISQRT_BITS: usize = {bits};"#).unwrap();

    println!("\n\n\nBEGIN:\n{s}");
}
